"use client";

import { AnimatePresence, motion, useIsPresent, useReducedMotion, type Transition } from "motion/react";
import {
  type ComponentPropsWithoutRef,
  type FocusEvent,
  type KeyboardEvent,
  type MouseEvent,
  type ReactNode,
  useEffect,
  useId,
  useRef,
  useState,
} from "react";

import { cn } from "@/lib/utils";

/** Props for a button that asks for confirmation inside itself before it acts. */
export interface ConfirmButtonProps {
  /** The action, such as "Delete project". */
  children: ReactNode;
  /** The question asked in place, such as "Delete this project?" */
  question: ReactNode;
  /**
   * Runs once the person confirms. Return a promise to keep the button busy
   * until it settles. A rejected promise returns to the question, so the
   * person can try again; show the error yourself.
   */
  onConfirm: () => void | Promise<void>;
  confirmLabel?: string;
  cancelLabel?: string;
  icon?: ReactNode;
  className?: string;
}

type Step = "idle" | "asking" | "working";

// Damping 41 is 2 × √420, rounded up: critically damped, so the button widens without overshoot.
const WIDEN: Transition = { type: "spring", stiffness: 420, damping: 41, mass: 1 };
// Reduced motion snaps the width and keeps the fade, because a fade is not motion.
const SNAP_AND_FADE: Transition = { width: { duration: 0 }, opacity: { duration: 0.15 } };
const FOLDED = { width: 0, opacity: 0 };
const UNFOLDED = { width: "auto", opacity: 1 };

const BUTTON =
  "inline-flex min-h-11 shrink-0 cursor-pointer touch-manipulation items-center justify-center gap-2 whitespace-nowrap rounded-full px-4 text-sm font-medium outline-none active:scale-97 aria-disabled:cursor-not-allowed aria-disabled:active:scale-100 focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring motion-safe:transition motion-safe:duration-150 sm:min-h-9";

// The arc spins at a constant speed: it stands for time passing, so easing would make it pulse.
function SpinnerGlyph() {
  return (
    <svg viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.75" aria-hidden="true" className="size-4 motion-safe:animate-spin">
      <circle cx="8" cy="8" r="5.5" className="opacity-25" />
      <path d="M8 2.5a5.5 5.5 0 0 1 5.5 5.5" strokeLinecap="round" />
    </svg>
  );
}

/**
 * One side of the button: the action, or the question. A side that is folding
 * away turns inert, so Tab cannot land on a button that is about to vanish.
 */
function Fold({
  transition,
  ...divProps
}: Pick<ComponentPropsWithoutRef<"div">, "role" | "aria-labelledby" | "className" | "children"> & { transition: Transition }) {
  const present = useIsPresent();
  return <motion.div {...divProps} initial={FOLDED} animate={UNFOLDED} exit={FOLDED} transition={transition} inert={!present} />;
}

/**
 * A destructive button that asks "Are you sure?" inside itself instead of in a
 * dialog. The first press widens it into the question with Cancel and the
 * action. Escape, Cancel or leaving it returns to the first state.
 */
export function ConfirmButton({
  children,
  question,
  onConfirm,
  confirmLabel = "Delete",
  cancelLabel = "Cancel",
  icon,
  className,
}: ConfirmButtonProps) {
  const [step, setStep] = useState<Step>("idle");
  // A folding segment keeps the props of its last render, so presses read the live step from here.
  const stepRef = useRef<Step>("idle");
  const groupRef = useRef<HTMLDivElement>(null);
  // Safari does not focus a button on click, so pressing Delete blurs with no
  // related target. A press inside the group must not read as leaving it.
  const pressing = useRef(false);
  // One controller removes both window listeners, whichever event ends the press.
  const pressEnd = useRef<AbortController | null>(null);
  // Set when the person clicks or tabs away while the action runs, so finishing does not pull focus back.
  const leftWhileWorking = useRef(false);
  const reduceMotion = useReducedMotion();
  const questionId = useId();
  const triggerRef = useRef<HTMLButtonElement>(null);
  const cancelRef = useRef<HTMLButtonElement>(null);
  // Focus follows the step: Cancel when the question opens, the trigger when it closes.
  const moveFocus = useRef(false);
  const mounted = useRef(true);
  useEffect(() => {
    mounted.current = true;
    return () => {
      mounted.current = false;
      pressEnd.current?.abort();
    };
  }, []);

  useEffect(() => {
    if (!moveFocus.current) return;
    moveFocus.current = false;
    if (step === "asking") cancelRef.current?.focus();
    if (step === "idle") triggerRef.current?.focus();
  }, [step]);

  const goTo = (next: Step, withFocus: boolean) => {
    moveFocus.current = withFocus;
    stepRef.current = next;
    setStep(next);
  };

  // Focus comes back only if the person did not move it elsewhere while the action ran.
  const focusStillHere = () => {
    if (leftWhileWorking.current) return false;
    const active = document.activeElement;
    return active === document.body || Boolean(groupRef.current?.contains(active));
  };

  const confirm = async (event: MouseEvent<HTMLButtonElement>) => {
    // The second click of the double-click that opened the question must not
    // confirm it. A keyboard press reports zero clicks and always counts.
    if (stepRef.current !== "asking" || event.detail > 1) return;
    leftWhileWorking.current = false;
    goTo("working", false);
    try {
      await onConfirm();
      if (mounted.current) goTo("idle", focusStillHere());
    } catch {
      if (mounted.current) goTo("asking", focusStillHere());
    }
  };

  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    if (event.key !== "Escape" || stepRef.current !== "asking") return;
    event.preventDefault();
    goTo("idle", true);
  };

  // A click elsewhere closes the question. Focus stays where the person put it.
  const onBlur = (event: FocusEvent<HTMLDivElement>) => {
    if (pressing.current || event.currentTarget.contains(event.relatedTarget)) return;
    if (stepRef.current === "working") leftWhileWorking.current = true;
    if (stepRef.current === "asking") goTo("idle", false);
  };

  const onPointerDown = () => {
    pressing.current = true;
    pressEnd.current?.abort();
    const controller = new AbortController();
    pressEnd.current = controller;
    const release = () => {
      pressing.current = false;
      controller.abort();
    };
    window.addEventListener("pointerup", release, { signal: controller.signal });
    window.addEventListener("pointercancel", release, { signal: controller.signal });
  };

  const transition = reduceMotion ? SNAP_AND_FADE : WIDEN;
  const working = step === "working";

  return (
    <div
      ref={groupRef}
      onKeyDown={onKeyDown}
      onBlur={onBlur}
      onPointerDown={onPointerDown}
      className={cn("inline-flex max-w-full items-center rounded-full border border-border bg-card p-1", className)}
    >
      <AnimatePresence initial={false}>
        {step === "idle" ? (
          <Fold key="trigger" transition={transition} className="flex overflow-hidden">
            <button
              ref={triggerRef}
              type="button"
              onClick={() => goTo("asking", true)}
              className={cn(BUTTON, "text-destructive hover:bg-destructive/10")}
            >
              {icon ? (
                <span aria-hidden="true" className="flex size-4 items-center justify-center">
                  {icon}
                </span>
              ) : null}
              {children}
            </button>
          </Fold>
        ) : (
          <Fold
            key="question"
            role="group"
            aria-labelledby={questionId}
            transition={transition}
            className="flex items-center gap-1 overflow-hidden"
          >
            <span id={questionId} className="whitespace-nowrap pl-3 pr-1 text-sm font-medium text-foreground">
              {question}
            </span>
            <button
              ref={cancelRef}
              type="button"
              aria-disabled={working || undefined}
              onClick={() => {
                if (stepRef.current === "asking") goTo("idle", true);
              }}
              className={cn(BUTTON, "text-foreground hover:bg-muted")}
            >
              {cancelLabel}
            </button>
            {/* Not disabled while it works: a disabled button drops keyboard focus. */}
            <button
              type="button"
              aria-disabled={working || undefined}
              aria-busy={working || undefined}
              onClick={confirm}
              className={cn(BUTTON, "border border-destructive/45 bg-destructive/10 text-destructive hover:bg-destructive/15")}
            >
              {working ? <SpinnerGlyph /> : null}
              {confirmLabel}
            </button>
          </Fold>
        )}
      </AnimatePresence>
    </div>
  );
}
